const root=document.documentElement,theme=document.querySelector('[data-theme-toggle]'),menu=document.querySelector('[data-menu]'),dialog=document.querySelector('dialog'),env=document.getElementById('environment-menu'),envButton=document.querySelector('[data-environments]');
const applyTheme=value=>{root.dataset.theme=value;theme?.setAttribute('aria-label',value==='dark'?'Ativar modo claro':'Ativar modo escuro')};applyTheme(localStorage.getItem('moves-theme')||'light');
theme?.addEventListener('click',()=>{const value=root.dataset.theme==='dark'?'light':'dark';localStorage.setItem('moves-theme',value);applyTheme(value)});menu?.addEventListener('click',()=>{const open=document.body.classList.toggle('menu-open');menu.setAttribute('aria-expanded',String(open))});document.querySelector('[data-backdrop]')?.addEventListener('click',()=>document.body.classList.remove('menu-open'));
envButton?.addEventListener('click',()=>{const open=env.hidden;env.hidden=!open;envButton.setAttribute('aria-expanded',String(open))});document.querySelector('[data-command]')?.addEventListener('click',()=>dialog.showModal());document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();dialog.showModal()}if(event.key==='Escape')document.body.classList.remove('menu-open')});
